-- SMART TVs & STREAMING (8 products)
('samsung-crystal-uhd-55-2026', 'Samsung 55" Crystal UHD 4K Smart TV 2026 - Titan Grey', 'tvs', 580000, 569000, 495000, 8, 15.5, '/assets/products/samsung-crystal-55.jpg', 'Transform your living room into a cinema. This 55-inch Crystal UHD TV features PurColor technology for lifelike shades, Crystal Processor 4K for intelligent upscaling, and Tizen OS with all major Nigerian streaming apps pre-installed.', 1, unixepoch('2026-06-16'), 1, 495000, '/assets/products/samsung-crystal-55.jpg', 535000, 4.6, 1, 'Samsung', 1, 1),

('lg-oled-c4-55', 'LG OLED C4 55" 4K Smart TV with AI Processor - Midnight Black', 'tvs', 1250000, 1215000, 1050000, 5, 16.3, '/assets/products/lg-oled-c4-55.jpg', 'Perfect blacks, infinite contrast. LG''s self-lit OLED pixels switch off completely for true black, while the α9 AI processor analyzes and optimizes every scene in real-time. A filmmaker''s vision delivered directly to your home.', 1, unixepoch('2026-06-16'), 1, 1050000, '/assets/products/lg-oled-c4-55.jpg', 1150000, 4.8, 1, 'LG', 1, 1),

('hisense-u8n-65-miniled', 'Hisense U8N 65" Mini-LED QLED 4K Google TV - Dark Grey', 'tvs', 850000, 829000, 720000, 6, 24.5, '/assets/products/hisense-u8n-65.jpg', 'Flagship picture quality at a fraction of the price. Mini-LED backlighting with 1,500 nits peak brightness and quantum dot color deliver a stunning HDR experience. Google TV with hands-free voice control makes finding content effortless.', 1, unixepoch('2026-06-16'), 1, 720000, '/assets/products/hisense-u8n-65.jpg', 780000, 4.7, 1, 'Hisense', 1, 1),

('tcl-c855-75-qd-miniled', 'TCL C855 75" QD-Mini LED 4K 144Hz Google TV', 'tvs', 1450000, 1420000, 1250000, 4, 28.0, '/assets/products/tcl-c855-75.jpg', 'A colossal 75-inch canvas for your entertainment. TCL''s QD-Mini LED technology delivers OLED-like contrast with quantum dot brilliance, while the 144Hz VRR panel makes this a gaming powerhouse. IMAX Enhanced and Dolby Vision IQ certified.', 1, unixepoch('2026-06-16'), 1, 1250000, '/assets/products/tcl-c855-75.jpg', 1350000, 4.7, 1, 'TCL', 1, 1),

('amazon-fire-tv-stick-4k-max-3', 'Amazon Fire TV Stick 4K Max Gen 3 Streaming Device', 'streaming', 45000, 43900, 36500, 50, 0.05, '/assets/products/firestick-4k-max-3.jpg', 'The most powerful streaming stick ever. With 16GB storage, WiFi 7 support, and a 2.4GHz octa-core processor, every app loads instantly. The Alexa Voice Remote Enhanced finds content across all your subscriptions with a single command.', 1, unixepoch('2026-06-16'), 1, 36500, '/assets/products/firestick-4k-max-3.jpg', 41500, 4.6, 1, 'Amazon', 1, 1),

('apple-tv-4k-4th-gen', 'Apple TV 4K 4th Gen 128GB with Ethernet - Silver', 'streaming', 185000, 179000, 152000, 15, 0.21, '/assets/products/apple-tv-4k-4.jpg', 'The ultimate streaming experience powered by the A18 Bionic chip. Dolby Vision, Dolby Atmos, and seamless integration with your Apple ecosystem make this the centerpiece of any smart home. Thread and Matter support for home automation.', 1, unixepoch('2026-06-16'), 1, 152000, '/assets/products/apple-tv-4k-4.jpg', 168000, 4.8, 1, 'Apple', 1, 1),

('xiaomi-tv-stick-5k', 'Xiaomi TV Stick 5K Google TV with Dolby Vision - Black', 'streaming', 28000, 26900, 22500, 65, 0.04, '/assets/products/xiaomi-tv-stick-5k.jpg', 'A whole world of entertainment in a device smaller than a chocolate bar. The Xiaomi TV Stick 5K delivers Dolby Vision and Dolby Atmos streaming via Google TV, with a dedicated YouTube and Netflix button on the Bluetooth remote.', 1, unixepoch('2026-06-16'), 1, 22500, '/assets/products/xiaomi-tv-stick-5k.jpg', 25500, 4.4, 1, 'Xiaomi', 1, 1),

('onn-google-tv-4k-pro-box', 'onn. Google TV 4K Pro Streaming Box with Smart Speaker', 'streaming', 35000, 33900, 28500, 40, 0.38, '/assets/products/onn-4k-pro-box.jpg', 'A streaming box that doubles as a smart speaker. The 4K Pro delivers smooth Google TV navigation with Dolby Atmos passthrough, a far-field microphone array for hands-free Google Assistant, and a compact design that blends into any entertainment center.', 1, unixepoch('2026-06-16'), 1, 28500, '/assets/products/onn-4k-pro-box.jpg', 31800, 4.3, 0, 'onn.', 1, 1),

-- KITCHEN & HOME APPLIANCES (10 products)
('ninja-creami-deluxe', 'Ninja CREAMi Deluxe Ice Cream & Frozen Treat Maker - Silver', 'appliances', 185000, 179000, 148000, 10, 5.9, '/assets/products/ninja-creami-deluxe.jpg', 'Turn anything into ice cream, sorbet, or gelato in minutes. The CREAMi Deluxe features a larger 900ml capacity, Dual Process technology for smoother results, and programs for milkshakes, frozen yogurt, and even protein ice cream.', 1, unixepoch('2026-06-16'), 1, 148000, '/assets/products/ninja-creami-deluxe.jpg', 168000, 4.7, 1, 'Ninja', 1, 1),

('instant-pot-duo-crisp-ultimate', 'Instant Pot Duo Crisp Ultimate 13-in-1 Air Fryer & Pressure Cooker', 'appliances', 220000, 215000, 178000, 12, 8.3, '/assets/products/instant-pot-ultimate.jpg', 'Thirteen appliances in one sleek design. Pressure cook, air fry, slow cook, steam, sauté, dehydrate, and more—all controlled by a vibrant touchscreen with guided cooking programs. The 6.2L capacity feeds the whole family.', 1, unixepoch('2026-06-16'), 1, 178000, '/assets/products/instant-pot-ultimate.jpg', 205000, 4.7, 1, 'Instant Pot', 1, 1),

('philips-airfryer-xxl-7000', 'Philips Airfryer XXL 7000 Series 8.3L with Rapid CombiAir - Black', 'appliances', 250000, 245000, 215000, 10, 7.5, '/assets/products/philips-xxl-7000.jpg', 'The world''s leading air fryer, perfected. Patented Rapid CombiAir technology circulates super-heated air at precisely controlled speeds, cooking food with up to 90% less fat while delivering crispy exteriors and tender interiors every time.', 1, unixepoch('2026-06-16'), 1, 215000, '/assets/products/philips-xxl-7000.jpg', 235000, 4.7, 1, 'Philips', 1, 1),

('vitamix-a3500i-ascent', 'Vitamix A3500i Ascent Series Smart Blender - Brushed Stainless', 'appliances', 480000, 469000, 410000, 6, 6.8, '/assets/products/vitamix-a3500i.jpg', 'The gold standard of blending. This self-cleaning smart blender features five program settings, a built-in wireless connectivity that auto-adjusts blending times, and aircraft-grade stainless steel blades that pulverize the toughest ingredients into silky-smooth perfection.', 1, unixepoch('2026-06-16'), 1, 410000, '/assets/products/vitamix-a3500i.jpg', 438000, 4.8, 0, 'Vitamix', 1, 1),

('nespresso-vertuo-pop-plus', 'Nespresso Vertuo Pop+ Coffee Machine by Magimix - Pacific Blue', 'appliances', 125000, 119000, 98000, 15, 3.8, '/assets/products/nespresso-vertuo-pop.jpg', 'Barista-quality coffee at the touch of a button. The Vertuo Pop+ uses centrifusion technology to read each capsule''s barcode and adjust brewing parameters, creating perfect espresso and full-bodied carafe coffee with a thick crema layer.', 1, unixepoch('2026-06-16'), 1, 98000, '/assets/products/nespresso-vertuo-pop.jpg', 112000, 4.6, 1, 'Nespresso', 1, 1),

('dyson-v16-detect-cordless', 'Dyson V16 Detect Absolute Cordless Vacuum - Gold/Nickel', 'appliances', 580000, 569000, 495000, 5, 3.2, '/assets/products/dyson-v16-detect.jpg', 'Reveals the invisible dust you can''t see. The V16 Detect features a piezoelectric sensor that counts and sizes particles 15,000 times per second, automatically increasing suction power when needed and displaying proof of a deep clean on the LCD screen.', 1, unixepoch('2026-06-16'), 1, 495000, '/assets/products/dyson-v16-detect.jpg', 535000, 4.8, 1, 'Dyson', 1, 1),

('levoit-core-600s-purifier', 'Levoit Core 600S Smart True HEPA Air Purifier - White', 'appliances', 220000, 215000, 178000, 10, 6.8, '/assets/products/levoit-core-600s.jpg', 'Breathe cleaner air in rooms up to 150m². The 3-stage H13 True HEPA filtration captures 99.97% of airborne particles down to 0.3 microns, while the smart laser sensor detects PM2.5 in real-time and auto-adjusts fan speed for optimal purification.', 1, unixepoch('2026-06-16'), 1, 178000, '/assets/products/levoit-core-600s.jpg', 205000, 4.7, 1, 'Levoit', 1, 1),

('breville-barista-express-impress', 'Breville Barista Express Impress Espresso Machine - Stainless Steel', 'appliances', 850000, 829000, 720000, 4, 10.5, '/assets/products/breville-impress.jpg', 'Third-wave specialty coffee at home. The Impress features an assisted tamping system that mimics a professional barista''s 22lb tamp, precise dose control, and a ThermoJet heating system that reaches optimal extraction temperature in 3 seconds.', 1, unixepoch('2026-06-16'), 1, 720000, '/assets/products/breville-impress.jpg', 780000, 4.8, 0, 'Breville', 1, 1),

('cosori-turboblaze-6l', 'COSORI TurboBlaze 6L Smart Air Fryer with WiFi - Dark Grey', 'appliances', 85000, 82900, 68000, 18, 5.5, '/assets/products/cosori-turboblaze.jpg', 'Smart cooking that simplifies your life. The TurboBlaze connects to the VeSync app for remote control and 200+ guided recipes. Its 360° Turbo air circulation cooks food 40% faster than a conventional oven with no preheating required.', 1, unixepoch('2026-06-16'), 1, 68000, '/assets/products/cosori-turboblaze.jpg', 78000, 4.6, 1, 'COSORI', 1, 1),

('xiaomi-smart-air-fryer-pro-8l', 'Xiaomi Smart Air Fryer Pro 8L with OLED Display - White', 'appliances', 65000, 62900, 52000, 22, 5.8, '/assets/products/xiaomi-airfryer-pro.jpg', 'Xiaomi''s largest air fryer for family meals. The 8L basket fits a whole chicken, while the OLED display and Mi Home app give you complete control over 150+ cloud-based recipes. Dual-speed fan technology ensures even cooking without shaking.', 1, unixepoch('2026-06-16'), 1, 52000, '/assets/products/xiaomi-airfryer-pro.jpg', 59000, 4.5, 1, 'Xiaomi', 1, 1),

-- PC COMPONENTS & GAMING GEAR (10 products)
('nvidia-geforce-rtx-5070', 'NVIDIA GeForce RTX 5070 12GB GDDR7 Founders Edition', 'pc-components', 650000, 639000, 555000, 6, 1.25, '/assets/products/rtx-5070.jpg', 'Next-gen Blackwell architecture brings cinematic path tracing and neural rendering to the mainstream. The RTX 5070 delivers RTX 4090-class performance with DLSS 4 and Reflex 2, redefining what a mid-range GPU can achieve.', 1, unixepoch('2026-06-16'), 1, 555000, '/assets/products/rtx-5070.jpg', 605000, 4.8, 1, 'NVIDIA', 1, 1),

('amd-ryzen-7-9700x', 'AMD Ryzen 7 9700X 8-Core 16-Thread AM5 Processor', 'pc-components', 350000, 339000, 295000, 10, 0.08, '/assets/products/ryzen-7-9700x.jpg', 'Zen 5 architecture delivers an unprecedented 20% IPC uplift over the previous generation. The 9700X boosts to 5.6GHz across 8 cores, with integrated RDNA 3.5 graphics and AI acceleration, making it the definitive choice for gaming and content creation.', 1, unixepoch('2026-06-16'), 1, 295000, '/assets/products/ryzen-7-9700x.jpg', 318000, 4.8, 1, 'AMD', 1, 1),

('corsair-rm1000x-shift', 'Corsair RM1000x SHIFT 1000W 80 PLUS Gold ATX 3.1 PSU - White', 'pc-components', 185000, 179000, 148000, 8, 2.5, '/assets/products/corsair-rm1000x-shift.jpg', 'Revolutionary side-mounted connectors make cable management effortless. The RM1000x SHIFT delivers clean, stable power with a 140mm magnetic levitation fan that stays silent under low loads, and full ATX 3.1 compliance for next-gen GPUs.', 1, unixepoch('2026-06-16'), 1, 148000, '/assets/products/corsair-rm1000x-shift.jpg', 168000, 4.7, 1, 'Corsair', 1, 1),

('samsung-990-pro-4tb-nvme', 'Samsung 990 PRO 4TB NVMe M.2 SSD PCIe 5.0 with Heatsink', 'pc-components', 350000, 339000, 288000, 8, 0.03, '/assets/products/samsung-990pro-4tb.jpg', 'Blistering 14,500MB/s sequential read speeds for massive game libraries and 8K video projects. The 990 PRO with hardware-accelerated AES 256-bit encryption ensures your data is as secure as it is fast. Samsung Magician software optimizes performance.', 1, unixepoch('2026-06-16'), 1, 288000, '/assets/products/samsung-990pro-4tb.jpg', 318000, 4.9, 1, 'Samsung', 1, 1),

('nzxt-h6-flow-rgb', 'NZXT H6 Flow RGB Dual-Chamber Mid-Tower Case - Matte Black', 'pc-components', 95000, 92900, 78000, 10, 8.5, '/assets/products/nzxt-h6-flow-rgb.jpg', 'Panoramic tempered glass wraps around the front and side, showcasing your build from every angle. The dual-chamber design isolates the PSU for cooler operation, while three pre-installed RGB fans and a mesh top panel ensure optimal airflow.', 1, unixepoch('2026-06-16'), 1, 78000, '/assets/products/nzxt-h6-flow-rgb.jpg', 88000, 4.7, 1, 'NZXT', 1, 1),

('arctic-liquid-freezer-iii-360', 'ARCTIC Liquid Freezer III 360 ARGB AIO CPU Cooler - Black', 'pc-components', 85000, 82900, 68000, 12, 1.68, '/assets/products/arctic-lf3-360.jpg', 'Silence meets extreme cooling capacity. The Liquid Freezer III features a redesigned pump, a 38mm-thick radiator that outperforms many 420mm AIOs, and a VRM fan that actively cools your motherboard, all while operating whisper-quiet at full load.', 1, unixepoch('2026-06-16'), 1, 68000, '/assets/products/arctic-lf3-360.jpg', 78000, 4.8, 1, 'ARCTIC', 1, 1),

('lian-li-sl-infinity-120-3pack', 'Lian Li UNI FAN SL-Infinity 120mm ARGB 3-Pack - Black', 'pc-components', 55000, 53900, 45000, 15, 0.65, '/assets/products/lian-li-sl-infinity.jpg', 'Interlocking fans that eliminate cable clutter. The SL-Infinity features a stunning infinity mirror ARGB design on both the hub and frame, daisy-chain power delivery, and L-Connect 3 software for precise control over 40 individually addressable LEDs per fan.', 1, unixepoch('2026-06-16'), 1, 45000, '/assets/products/lian-li-sl-infinity.jpg', 50500, 4.7, 1, 'Lian Li', 1, 1),

('logitech-g-pro-x-superlight-3', 'Logitech G Pro X Superlight 3 Wireless Gaming Mouse - Magenta', 'pc-components', 165000, 159000, 135000, 10, 0.06, '/assets/products/logitech-gpx3.jpg', 'The mouse that won countless esports championships gets its biggest upgrade yet. At 58 grams with the new HERO 3 sensor tracking at 44,000 DPI, optical hybrid switches, and 120-hour battery life, it remains the undisputed choice of professionals.', 1, unixepoch('2026-06-16'), 1, 135000, '/assets/products/logitech-gpx3.jpg', 149000, 4.9, 1, 'Logitech', 1, 1),

('razer-viper-v4-pro', 'Razer Viper V4 Pro 8K Hz Wireless Esports Mouse - White', 'pc-components', 175000, 169000, 142000, 8, 0.06, '/assets/products/razer-viper-v4.jpg', 'True 8,000Hz wireless polling delivers sub-0.125ms input latency. The Focus Pro 45K optical sensor, Gen-4 optical switches, and a 59g ultra-lightweight body make the Viper V4 Pro the most responsive mouse ever created for competitive gaming.', 1, unixepoch('2026-06-16'), 1, 142000, '/assets/products/razer-viper-v4.jpg', 158000, 4.8, 1, 'Razer', 1, 1),

('steelseries-arctis-nova-pro-x', 'SteelSeries Arctis Nova Pro X Wireless Gaming Headset - Black', 'audio', 320000, 315000, 268000, 6, 0.52, '/assets/products/arctis-nova-pro-x.jpg', 'Audiophile-grade gaming audio with simultaneous 2.4GHz wireless and Bluetooth. The GameDAC Gen 3 with ESS Sabre Quad-DAC delivers 96kHz/24-bit hi-res audio, while the fully retractable ClearCast Gen 3 microphone ensures your squad hears you with broadcast quality.', 1, unixepoch('2026-06-16'), 1, 268000, '/assets/products/arctis-nova-pro-x.jpg', 298000, 4.8, 1, 'SteelSeries', 1, 1),

-- KIDS TECH & EDUCATIONAL (8 products)
('amazon-fire-hd-12-kids-pro', 'Amazon Fire HD 12 Kids Pro Tablet 256GB - Cyber Blue', 'kids-tech', 185000, 179000, 148000, 15, 0.75, '/assets/products/fire-hd-12-kids.jpg', 'A tablet built for growing minds ages 6-12. The 12-inch display is protected by a kid-proof case, while the 2-year worry-free guarantee means if it breaks, Amazon replaces it. One year of Amazon Kids+ included with thousands of ad-free books and games.', 1, unixepoch('2026-06-16'), 1, 148000, '/assets/products/fire-hd-12-kids.jpg', 168000, 4.6, 1, 'Amazon', 1, 1),

('vtech-kidizoom-smartwatch-dx5', 'VTech Kidizoom Smartwatch DX5 - Galactic Blue', 'kids-tech', 35000, 33900, 28500, 30, 0.12, '/assets/products/vtech-kidizoom-dx5.jpg', 'The ultimate smartwatch built exclusively for kids aged 4-9. Dual cameras for photos and selfies, 50+ 3D animated watch faces, motion sensor games, a pedometer, and a secure parent-controlled friend connection that works without a cellular plan.', 1, unixepoch('2026-06-16'), 1, 28500, '/assets/products/vtech-kidizoom-dx5.jpg', 31800, 4.5, 1, 'VTech', 1, 1),

('osmo-genius-starter-kit-2026', 'Osmo Genius Starter Kit 2026 for iPad - Interactive Learning', 'kids-tech', 85000, 82900, 68000, 12, 1.15, '/assets/products/osmo-genius-2026.jpg', 'Transform screen time into hands-on learning. The Osmo kit turns your iPad into an interactive classroom where physical tiles, shapes, and drawing tools teach math, spelling, problem-solving, and creativity through five award-winning games.', 1, unixepoch('2026-06-16'), 1, 68000, '/assets/products/osmo-genius-2026.jpg', 78000, 4.7, 1, 'Osmo', 1, 1),

('lego-boost-creative-toolbox-3', 'LEGO Boost Creative Toolbox 3 - 5-in-1 Coding Robot Kit', 'kids-tech', 125000, 119000, 98000, 10, 1.5, '/assets/products/lego-boost-3.jpg', 'Build, code, and play with five different programmable robots. The intuitive drag-and-drop coding app teaches children aged 7+ the fundamentals of programming while they bring their LEGO creations to life with motors, sensors, and 1,100+ pieces.', 1, unixepoch('2026-06-16'), 1, 98000, '/assets/products/lego-boost-3.jpg', 112000, 4.8, 0, 'LEGO', 1, 1),

('sphero-bolt-2', 'Sphero BOLT 2 Programmable Robot Ball with Matrix Display - Clear', 'kids-tech', 125000, 119000, 98000, 8, 0.45, '/assets/products/sphero-bolt-2.jpg', 'A glowing orb that teaches coding through play. The BOLT 2 features an 8x8 LED matrix that displays animations and data, multiple sensors including a gyroscope and light sensor, and supports JavaScript and block-based programming via the Sphero Edu app.', 1, unixepoch('2026-06-16'), 1, 98000, '/assets/products/sphero-bolt-2.jpg', 112000, 4.6, 0, 'Sphero', 1, 1),

('amazon-glow-2026', 'Amazon Glow 2026 Interactive Video Calling & Learning Device', 'kids-tech', 220000, 215000, 178000, 6, 2.1, '/assets/products/amazon-glow-2026.jpg', 'Long-distance grandparent visits transformed. The Glow projects an interactive 19-inch touch-sensitive space onto any table where kids can read, draw, play games, and solve puzzles with remote family members in real-time via a secure video call.', 1, unixepoch('2026-06-16'), 1, 178000, '/assets/products/amazon-glow-2026.jpg', 205000, 4.4, 0, 'Amazon', 1, 1),

('tonies-audio-box-2026', 'Tonies Audio Box 2026 Screen-Free Audio Player - Starter Set', 'kids-tech', 65000, 63900, 52000, 18, 0.65, '/assets/products/tonies-box-2026.jpg', 'Screen-free storytelling magic for children aged 3+. Place a hand-painted Tonie character on the box and it magically plays stories, songs, and educational content. The 2026 model features 14-hour battery life and 16GB internal storage for Creative-Tonies.', 1, unixepoch('2026-06-16'), 1, 52000, '/assets/products/tonies-box-2026.jpg', 59000, 4.7, 1, 'Tonies', 1, 1),

('makeblock-mbot2-neo', 'Makeblock mBot2 Neo Coding Robot with AI Camera - Blue', 'kids-tech', 125000, 119000, 98000, 10, 1.2, '/assets/products/mbot2-neo.jpg', 'A robot that grows with your child''s coding skills. The mBot2 Neo features an AI camera for object recognition, line-following sensors, and an ultrasonic obstacle avoidance sensor, programmable via Scratch block-based coding or advanced Python for teens.', 1, unixepoch('2026-06-16'), 1, 98000, '/assets/products/mbot2-neo.jpg', 112000, 4.6, 1, 'Makeblock', 1, 1),

-- OFFICE & PRODUCTIVITY TECH (7 products)
('fujitsu-scansnap-ix1600', 'Fujitsu ScanSnap iX1600 Wireless Document Scanner - White', 'office-tech', 380000, 369000, 315000, 6, 3.4, '/assets/products/fujitsu-ix1600.jpg', 'Go paperless with one touch. The iX1600 scans 40 double-sided pages per minute to searchable PDFs, cloud services, or your phone via WiFi. The 4.3-inch touchscreen lets you create up to 30 customizable scan profiles for different workflows.', 1, unixepoch('2026-06-16'), 1, 315000, '/assets/products/fujitsu-ix1600.jpg', 348000, 4.7, 0, 'Fujitsu', 1, 1),

('brother-hl-l2460dw-wireless', 'Brother HL-L2460DW Wireless Duplex Laser Printer - Compact', 'office-tech', 185000, 179000, 148000, 12, 7.2, '/assets/products/brother-hl-l2460dw.jpg', 'Reliable, fast monochrome printing that fits on any desk. This compact laser printer delivers 32ppm duplex printing, automatic double-sided output, and wireless connectivity for printing directly from your phone, tablet, or laptop without drivers.', 1, unixepoch('2026-06-16'), 1, 148000, '/assets/products/brother-hl-l2460dw.jpg', 168000, 4.6, 1, 'Brother', 1, 1),

('epson-ecotank-l6590-aio', 'Epson EcoTank L6590 A4 Multifunction Ink Tank Printer', 'office-tech', 350000, 339000, 288000, 8, 9.7, '/assets/products/epson-l6590.jpg', 'Two years of ink included in the box—enough for 14,000 black and 7,200 color pages. This business-class all-in-one prints, scans, copies, and faxes with a 35-page ADF, automatic duplexing, and Ethernet/WiFi/WiFi Direct connectivity for the modern office.', 1, unixepoch('2026-06-16'), 1, 288000, '/assets/products/epson-l6590.jpg', 318000, 4.7, 1, 'Epson', 1, 1),

('logitech-brio-ultra-hd-pro', 'Logitech Brio Ultra HD Pro 4K Webcam with Windows Hello', 'office-tech', 125000, 119000, 98000, 15, 0.13, '/assets/products/logitech-brio-pro.jpg', 'Look your best in every meeting with 4K resolution, HDR, and RightLight 3 auto-light correction. The Brio supports Windows Hello facial recognition for instant, secure login and features a 90° field of view perfect for individual or small group calls.', 1, unixepoch('2026-06-16'), 1, 98000, '/assets/products/logitech-brio-pro.jpg', 112000, 4.7, 1, 'Logitech', 1, 1),

('yubico-yubikey-5c-nfc-fips', 'Yubico YubiKey 5C NFC FIPS Hardware Security Key', 'office-tech', 65000, 63900, 52000, 25, 0.01, '/assets/products/yubikey-5c-nfc.jpg', 'The strongest defense against account takeovers. This FIPS 140-3 certified security key supports passwordless authentication, one-time passwords, and public-key cryptography across USB-C and NFC, protecting your most sensitive accounts from phishing and credential theft.', 1, unixepoch('2026-06-16'), 1, 52000, '/assets/products/yubikey-5c-nfc.jpg', 59000, 4.8, 0, 'Yubico', 1, 1),

('anker-powerconf-c300', 'Anker PowerConf C300 1080p AI Webcam with Auto-Framing', 'office-tech', 85000, 82900, 68000, 18, 0.11, '/assets/products/anker-powerconf-c300.jpg', 'An AI camera operator built into your webcam. The PowerConf C300 uses artificial intelligence to automatically adjust the field of view, keeping you centered even if you move, while 1080p HDR and dual stereo microphones ensure you''re seen and heard clearly.', 1, unixepoch('2026-06-16'), 1, 68000, '/assets/products/anker-powerconf-c300.jpg', 78000, 4.6, 1, 'Anker', 1, 1),

('timeular-zei-8-sided-dice', 'Timeular ZEI 8-Sided Time Tracking Dice with App - White', 'office-tech', 85000, 82900, 68000, 10, 0.38, '/assets/products/timeular-zei.jpg', 'Effortless time tracking for freelancers and consultants. Flip this physical 8-sided dice to the side representing your current task, and the companion app automatically logs your time. A tactile, satisfying way to bill every minute accurately.', 1, unixepoch('2026-06-16'), 1, 68000, '/assets/products/timeular-zei.jpg', 78000, 4.3, 0, 'Timeular', 1, 1),

-- PORTABLE POWER STATIONS (7 products)
('ecoflow-river-3-pro', 'EcoFlow RIVER 3 Pro 768Wh Portable Power Station', 'power-stations', 450000, 439000, 380000, 8, 7.8, '/assets/products/ecoflow-river-3-pro.jpg', 'Fastest charging portable power station in its class—0 to 100% in 55 minutes via AC. With 768Wh capacity, 1600W AC output (X-Boost to 2400W), and a modular design, it''s the ultimate power backup for Nigerian homes, fieldwork, and outdoor events.', 1, unixepoch('2026-06-16'), 1, 380000, '/assets/products/ecoflow-river-3-pro.jpg', 415000, 4.7, 1, 'EcoFlow', 1, 1),

('jackery-explorer-1000-v3', 'Jackery Explorer 1000 v3 1070Wh LiFePO4 Solar Generator', 'power-stations', 580000, 569000, 495000, 6, 10.8, '/assets/products/jackery-explorer-1000.jpg', 'A decade of reliable backup power. The Explorer 1000 v3 uses a LiFePO4 battery rated for 4,000 charge cycles—that''s over 10 years of daily use. With 1500W AC output, silent operation, and solar input, it keeps your essentials running during extended blackouts.', 1, unixepoch('2026-06-16'), 1, 495000, '/assets/products/jackery-explorer-1000.jpg', 535000, 4.7, 0, 'Jackery', 1, 1),

('bluetti-ac180p', 'BLUETTI AC180P 1440Wh Portable Power Station with UPS', 'power-stations', 680000, 659000, 575000, 5, 16.5, '/assets/products/bluetti-ac180p.jpg', 'Seamless 15ms UPS switchover protects your sensitive electronics during power cuts. The AC180P delivers 1800W of pure sine wave power from a massive 1440Wh LiFePO4 battery, with 1440W solar input that charges from zero to full in under 2 hours of Nigerian sun.', 1, unixepoch('2026-06-16'), 1, 575000, '/assets/products/bluetti-ac180p.jpg', 625000, 4.8, 1, 'BLUETTI', 1, 1),

('anker-solix-c1000x', 'Anker SOLIX C1000X 1056Wh Portable Power Station with Solar Panel', 'power-stations', 520000, 509000, 445000, 7, 12.0, '/assets/products/anker-solix-c1000x.jpg', 'Anker reliability in a portable power station. The SOLIX C1000X features HyperFlash 1300W AC charging for a full recharge in 58 minutes, a 10-year lifespan LiFePO4 battery, and an included 200W solar panel for sustainable off-grid power anywhere in Nigeria.', 1, unixepoch('2026-06-16'), 1, 445000, '/assets/products/anker-solix-c1000x.jpg', 485000, 4.7, 1, 'Anker', 1, 1),

('goal-zero-yeti-500x', 'Goal Zero Yeti 500X 505Wh Portable Power Station with WiFi', 'power-stations', 320000, 315000, 268000, 8, 5.8, '/assets/products/goal-zero-yeti-500x.jpg', 'Monitor and control your power remotely via the Goal Zero app. The Yeti 500X provides 505Wh of clean, silent power for lights, laptops, CPAP machines, and small appliances, with multiple output options including AC, USB-C PD 60W, and regulated 12V.', 1, unixepoch('2026-06-16'), 1, 268000, '/assets/products/goal-zero-yeti-500x.jpg', 298000, 4.5, 0, 'Goal Zero', 1, 1),

('oraimo-powerstation-300w', 'Oraimo PowerStation 300W 80000mAh Portable Generator', 'power-stations', 125000, 119000, 98000, 12, 3.2, '/assets/products/oraimo-powerstation-300.jpg', 'Oraimo enters the portable power station market with a compact, affordable unit perfect for charging laptops, phones, and small electronics during power outages. The 300W pure sine wave AC outlet and 100W USB-C PD keep your essential devices running.', 1, unixepoch('2026-06-16'), 1, 98000, '/assets/products/oraimo-powerstation-300.jpg', 112000, 4.4, 1, 'Oraimo', 1, 1),

('genki-moonlight-1000', 'Genki Moonlight 1000W Portable Power Station with Integrated LED Light', 'power-stations', 420000, 409000, 355000, 6, 9.5, '/assets/products/genki-moonlight-1000.jpg', 'Purpose-built for Nigeria''s creative community. The Moonlight 1000 features a built-in 100W COB LED panel with adjustable color temperature for video shoots, alongside 1000Wh capacity and 1500W AC output for running cameras, lights, and laptops on location.', 1, unixepoch('2026-06-16'), 1, 355000, '/assets/products/genki-moonlight-1000.jpg', 388000, 4.5, 0, 'Genki', 1, 1);
